12	// agentAncestryDepth is how many ancestors the session-start hook records in
13	// SessionState.AgentAncestry. The chain above the hook is (shell that ran the
14	// hook) → agent → (terminal shell / supervisor); three levels reliably
15	// includes the agent process while staying below system-wide ancestors
16	// (terminal multiplexers, init) that would make unrelated processes look
17	// related.
18	const agentAncestryDepth = 3
19	
20	// commitAncestryDepth is how far the commit hook walks its own ancestry when
21	// matching — deeper than the recording depth because agents interpose shells
22	// and wrappers between themselves and the git subprocess (hook ← git ← tool
23	// shell(s) ← agent ← ...).
24	const commitAncestryDepth = 12
25	
26	// findSessionsForCommitLinking resolves which sessions a commit belongs to:
27	// the worktree-matched set (a commit captures the worktree's content, so
28	// every session with pending content here belongs in it — concurrent
29	// sessions interleave by design) PLUS the identity-matched session when the
30	// committing process's ancestry names one that worktree matching missed.
31	// The identity union is what makes an agent-made commit immune to worktree
32	// bookkeeping drift: an agent committing in a sibling worktree still links
33	// to its own session (guest-linked), where path matching alone found nothing
34	// or declined as ambiguous.
35	func (s *ManualCommitStrategy) findSessionsForCommitLinking(ctx context.Context, worktreePath string) ([]*SessionState, error) {
36		sessions, err := s.findSessionsForWorktree(ctx, worktreePath)
37		if err != nil {
38			sessions = nil // identity below may still rescue linking
39		}
40		if guest := s.findSessionByCommitAncestry(ctx); guest != nil && !linkingSetContains(sessions, guest.SessionID) {
41			sessions = append(sessions, guest)
42			err = nil
43		}
44		return sessions, err
45	}
46	
47	func linkingSetContains(states []*SessionState, id string) bool {
48		for _, st := range states {
49			if st.SessionID == id {
50				return true
51			}
52		}
53		return false
54	}
55	
56	// findSessionByCommitAncestry attributes the running commit to the session
57	// whose recorded agent process is an ancestor of this hook process. Nearest
58	// ancestor wins: if two sessions recorded processes at different depths of
59	// this commit's ancestry (an agent vs. the terminal shell it runs in), the
60	// one closest to the commit is the author. Ties at the same depth — the same
61	// live process recorded by several sessions, e.g. a resumed agent — go to
62	// the most recently interacting session. Imported sessions are historical
63	// records and never match. Returns nil when nothing in the ancestry is a
64	// recorded agent (the caller falls back to worktree matching).
65	func (s *ManualCommitStrategy) findSessionByCommitAncestry(ctx context.Context) *SessionState {
66		ancestors := proctree.Ancestors(commitAncestryDepth)
67		if len(ancestors) == 0 {
68			return nil
69		}
70		states, err := s.listAllSessionStates(ctx)
71		if err != nil || len(states) == 0 {
72			return nil
73		}
74	
75		for _, anc := range ancestors { // nearest-first
76			var best *SessionState
77			for _, state := range states {
78				if state.Kind.IsImported() || !refsContain(state.AgentAncestry, anc) {
79					continue
80				}
81				if best == nil || interactedAfter(state, best) {
82					best = state
83				}
84			}
85			if best != nil {
86				logging.Debug(logging.WithComponent(ctx, "checkpoint"),
87					"commit attributed to session by process ancestry",
88					slog.String("session_id", best.SessionID),
89					slog.Int("ancestor_pid", anc.PID),
90					slog.String("ancestor_exe", anc.Exe),
91				)
92				return best
93			}
94		}
95		return nil
96	}
97	
98	// isSessionHomeWorktree reports whether the current worktree is the one the
99	// session is recorded in. Worktree-coupled state (BaseCommit, shadow-branch
100	// realignment) may only be mutated from the session's home worktree; a
101	// guest-linked commit elsewhere condenses and links without moving it.
102	// Unresolvable worktree reads as home, preserving pre-identity behavior.
103	func isSessionHomeWorktree(ctx context.Context, state *SessionState) bool {
104		worktreePath, err := paths.WorktreeRoot(ctx)
105		if err != nil || worktreePath == "" {
106			return true
107		}
108		return state.WorktreePath == "" || state.WorktreePath == worktreePath
109	}
110	
111	func refsContain(refs []proctree.ProcessRef, target proctree.ProcessRef) bool {
112		for _, r := range refs {
113			if r.SameProcess(target) {
114				return true
115			}
116		}
117		return false
118	}
119	
120	func interactedAfter(a, b *SessionState) bool {
121		if a.LastInteractionTime == nil {
122			return false
123		}
124		if b.LastInteractionTime == nil {
125			return true
126		}
127		return a.LastInteractionTime.After(*b.LastInteractionTime)
128	}

