func NewStateStore(ctx context.Context) (*StateStore, error) {
	commonDir, err := getGitCommonDir(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get git common dir: %w", err)
	}
	if err := ensureTestIsolatedStateDir(commonDir); err != nil {
